css:
:where(.wtyg-map-abortion_grid) *{box-sizing:border-box}
:where(.wtyg-map-abortion_grid),:where(.wtyg-map-abortion_grid){margin:0;height:100%;background:#101315;color:#e4e0d8;font:14px/1.45 "Source Sans 3","Source Sans Pro",system-ui,sans-serif}
:where(.wtyg-map-abortion_grid) :is([data-wtyg-id="map"],#wtyg-noid-map){position:absolute;inset:0;background:#101315}
:where(.wtyg-map-abortion_grid) .leaflet-container{background:#101315;font:inherit}
:where(.wtyg-map-abortion_grid) .leaflet-popup-content-wrapper,:where(.wtyg-map-abortion_grid) .leaflet-popup-tip{background:#191d20;color:#e4e0d8;border:1px solid #2d3438;box-shadow:0 4px 18px rgba(0,0,0,.55)}
:where(.wtyg-map-abortion_grid) .leaflet-popup-content{margin:12px 14px;font-size:13px;line-height:1.45}
:where(.wtyg-map-abortion_grid) .leaflet-popup-content a,:where(.wtyg-map-abortion_grid) .panel a,:where(.wtyg-map-abortion_grid) :is([data-wtyg-id="about"],#wtyg-noid-about) a,:where(.wtyg-map-abortion_grid) :is([data-wtyg-id="frame"],#wtyg-noid-frame) a{color:#8fc3d0}
:where(.wtyg-map-abortion_grid) .leaflet-container a.leaflet-popup-close-button{color:#9aa3a8}
:where(.wtyg-map-abortion_grid) .pp h3{margin:0 0 4px;font:600 15px/1.3 "Source Serif 4","Source Serif Pro",Georgia,serif;color:#f1ede5}
:where(.wtyg-map-abortion_grid) .pp .meta{color:#9aa3a8;font-size:12px;margin:2px 0 6px}
:where(.wtyg-map-abortion_grid) .pp .tag{display:inline-block;padding:1px 7px;border-radius:9px;font-size:11.5px;margin:0 4px 4px 0;background:#263035;color:#dfe8ea;border:1px solid #33424a}
:where(.wtyg-map-abortion_grid) .pp p{margin:6px 0}
:where(.wtyg-map-abortion_grid) .pp details{margin:6px 0;border-top:1px solid #2a3135;padding-top:4px}
:where(.wtyg-map-abortion_grid) .pp summary{cursor:pointer;color:#b8d4da;font-size:12.5px}
:where(.wtyg-map-abortion_grid) .tw{overflow:auto;max-width:100%}
:where(.wtyg-map-abortion_grid) table.kv{border-collapse:collapse;width:100%;font-size:12px;margin:4px 0}
:where(.wtyg-map-abortion_grid) table.kv th{text-align:left;vertical-align:top;color:#9aa3a8;font-weight:600;padding:2px 8px 2px 0;width:34%}
:where(.wtyg-map-abortion_grid) table.kv td{padding:2px 0;vertical-align:top;word-break:break-word}
:where(.wtyg-map-abortion_grid) table.grid{border-collapse:collapse;font-size:11.5px;margin:4px 0}
:where(.wtyg-map-abortion_grid) table.grid th,:where(.wtyg-map-abortion_grid) table.grid td{border:1px solid #2a3135;padding:2px 5px;vertical-align:top;text-align:left}
:where(.wtyg-map-abortion_grid) table.grid th{color:#9aa3a8;background:#1d2326}
:where(.wtyg-map-abortion_grid) .src{font-size:11.5px;color:#9aa3a8;margin-top:6px}
:where(.wtyg-map-abortion_grid) .src ol{margin:2px 0 0 18px;padding:0}
:where(.wtyg-map-abortion_grid) .fd ul{margin:2px 0 0 18px;padding:0}
:where(.wtyg-map-abortion_grid) .btn,:where(.wtyg-map-abortion_grid) .wtyg-frame{font:inherit;font-size:12.5px;background:#23343a;color:#e4eef0;border:1px solid #3e5a63;border-radius:3px;padding:3px 9px;cursor:pointer;margin:4px 6px 4px 0}
:where(.wtyg-map-abortion_grid) .btn:hover,:where(.wtyg-map-abortion_grid) .wtyg-frame:hover{background:#2c4650}
:where(.wtyg-map-abortion_grid) .note{font-size:11.5px;color:#9aa3a8}
:where(.wtyg-map-abortion_grid) .panel{position:absolute;z-index:1000;left:12px;top:12px;width:340px;max-width:calc(100vw - 24px);max-height:calc(100vh - 24px);overflow:auto;background:rgba(19,23,25,.95);border:1px solid #2d3438;border-radius:4px;padding:12px 14px}
:where(.wtyg-map-abortion_grid) .panel h1{margin:0 0 4px;font:600 17px/1.25 "Source Serif 4","Source Serif Pro",Georgia,serif;color:#f1ede5}
:where(.wtyg-map-abortion_grid) .panel .sub{color:#9aa3a8;font-size:12.5px;margin-bottom:8px}
:where(.wtyg-map-abortion_grid) .panel label{display:block;font-size:12px;color:#9aa3a8;margin:8px 0 3px}
:where(.wtyg-map-abortion_grid) .panel select,:where(.wtyg-map-abortion_grid) .panel input{width:100%;font:inherit;font-size:13px;background:#1b2124;color:#e4e0d8;border:1px solid #33404a;border-radius:3px;padding:4px 6px}
:where(.wtyg-map-abortion_grid) .legend{margin-top:8px;font-size:12px}
:where(.wtyg-map-abortion_grid) .legend .row{display:flex;align-items:center;gap:7px;margin:2px 0}
:where(.wtyg-map-abortion_grid) .legend .sw{width:14px;height:12px;border-radius:2px;flex:0 0 auto;border:1px solid rgba(255,255,255,.15)}
:where(.wtyg-map-abortion_grid) .legend .src2{color:#9aa3a8;font-size:11.5px;margin-top:4px}
:where(.wtyg-map-abortion_grid) .hits{font-size:12px;margin-top:4px;max-height:170px;overflow:auto}
:where(.wtyg-map-abortion_grid) .hits div{cursor:pointer;padding:2px 0;border-bottom:1px solid #22292c}
:where(.wtyg-map-abortion_grid) .hits div:hover{color:#fff}
:where(.wtyg-map-abortion_grid) .leaflet-control-layers{background:rgba(19,23,25,.95)!important;color:#e4e0d8;border:1px solid #2d3438!important;max-height:calc(100vh - 150px);overflow:auto;max-width:330px;font-size:12.5px}
:where(.wtyg-map-abortion_grid) .leaflet-control-layers label{margin:3px 0}
:where(.wtyg-map-abortion_grid) .leaflet-control-layers-overlays .sw{display:inline-block;width:10px;height:10px;border-radius:50%;margin:0 5px 0 2px;vertical-align:-1px}
:where(.wtyg-map-abortion_grid) .leaflet-control-attribution{background:rgba(16,19,21,.8)!important;color:#7d868b}
:where(.wtyg-map-abortion_grid) .leaflet-control-attribution a{color:#8fb0b8}
:where(.wtyg-map-abortion_grid) :is([data-wtyg-id="frame"],#wtyg-noid-frame){position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);width:min(1100px,94vw);height:88vh;z-index:3000;display:none;flex-direction:column;background:#151a1c;border:1px solid #33404a;border-radius:4px;box-shadow:0 8px 30px rgba(0,0,0,.6)}
:where(.wtyg-map-abortion_grid) :is([data-wtyg-id="frame"],#wtyg-noid-frame).small{left:auto;top:auto;right:14px;bottom:14px;transform:none;width:min(480px,92vw);height:62vh}
:where(.wtyg-map-abortion_grid) :is([data-wtyg-id="frame"],#wtyg-noid-frame) .bar{display:flex;gap:9px;align-items:center;padding:6px 10px;border-bottom:1px solid #2d3438;font-size:12.5px}
:where(.wtyg-map-abortion_grid) :is([data-wtyg-id="frame"],#wtyg-noid-frame) .bar b{flex:1;color:#f1ede5;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
:where(.wtyg-map-abortion_grid) :is([data-wtyg-id="frame"],#wtyg-noid-frame) .bar button{font:inherit;background:none;border:1px solid #3a464c;border-radius:2px;color:#cfd8db;cursor:pointer;padding:1px 7px}
:where(.wtyg-map-abortion_grid) :is([data-wtyg-id="frame"],#wtyg-noid-frame) iframe{flex:1;width:100%;border:0;background:#fff}
:where(.wtyg-map-abortion_grid) :is([data-wtyg-id="frame"],#wtyg-noid-frame) .fnote{padding:4px 10px;font-size:11.5px;color:#9aa3a8;border-top:1px solid #2d3438}
:where(.wtyg-map-abortion_grid) :is([data-wtyg-id="about"],#wtyg-noid-about){position:fixed;inset:0;z-index:3500;display:none;background:rgba(8,10,11,.72)}
:where(.wtyg-map-abortion_grid) :is([data-wtyg-id="about"],#wtyg-noid-about) .in{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:min(860px,94vw);max-height:90vh;overflow:auto;background:#161a1d;border:1px solid #33404a;border-radius:4px;padding:16px 20px}
:where(.wtyg-map-abortion_grid) :is([data-wtyg-id="about"],#wtyg-noid-about) h2{font:600 18px "Source Serif 4","Source Serif Pro",Georgia,serif;margin:0 0 8px;color:#f1ede5}
:where(.wtyg-map-abortion_grid) :is([data-wtyg-id="about"],#wtyg-noid-about) h3{font:600 14.5px "Source Serif 4","Source Serif Pro",Georgia,serif;margin:14px 0 4px;color:#e8e2d6}
:where(.wtyg-map-abortion_grid) :is([data-wtyg-id="about"],#wtyg-noid-about) p,:where(.wtyg-map-abortion_grid) :is([data-wtyg-id="about"],#wtyg-noid-about) li{font-size:13px}
:where(.wtyg-map-abortion_grid) :is([data-wtyg-id="about"],#wtyg-noid-about) .x{position:sticky;top:0;float:right;font:inherit;background:none;border:1px solid #3a464c;color:#cfd8db;border-radius:2px;cursor:pointer}
:where(.wtyg-map-abortion_grid) .ptoggle{float:right;font:inherit;font-size:11.5px;background:none;border:1px solid #3a464c;color:#cfd8db;border-radius:2px;cursor:pointer;padding:1px 6px;margin-left:6px}
:where(.wtyg-map-abortion_grid) .panel.folded .pbody{display:none}
:where(.wtyg-map-abortion_grid) .panel.folded{width:auto}
:where(.wtyg-map-abortion_grid) .ltoggle{display:block;width:100%;text-align:left;font:inherit;font-size:12px;background:none;border:0;border-bottom:1px solid #2d3438;color:#cfd8db;cursor:pointer;padding:2px 2px 4px;margin-bottom:4px}
:where(.wtyg-map-abortion_grid) .leaflet-control-layers.folded .leaflet-control-layers-list{display:none}
:where(.wtyg-map-abortion_grid) .leaflet-control-layers.folded .ltoggle{border:0;margin:0}
:where(.wtyg-map-abortion_grid) .setbox{margin-top:10px;padding-top:8px;border-top:1px solid #2a3135}
:where(.wtyg-map-abortion_grid) .worldbtn{font:inherit;font-size:12px;background:#1b2124;color:#e4e0d8;border:1px solid #3a464c;border-radius:4px;padding:5px 9px;cursor:pointer;box-shadow:0 1px 4px rgba(0,0,0,.5)}
:where(.wtyg-map-abortion_grid) .worldbtn:hover{background:#26323a}
:where(.wtyg-map-abortion_grid) .leaflet-bar a{background:#1b2124!important;color:#e4e0d8!important;border-color:#3a464c!important}
@media (max-width:640px){:where(.wtyg-map-abortion_grid) .panel{width:auto;right:12px;max-height:42vh}
:where(.wtyg-map-abortion_grid) .leaflet-control-layers{max-height:40vh}}
